namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _sut = new();

    // --- ChargeAsync Tests ---

    [TestMethod]
    [DataRow("tok_valid_visa", 49.99, DisplayName = "Standard amount")]
    [DataRow("tok_valid_mc", 0.01, DisplayName = "Minimum positive amount")]
    [DataRow("tok_valid_amex", 9999.99, DisplayName = "Large amount")]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccessWithChargeId(
        string cardToken, double amount)
    {
        var result = await _sut.ChargeAsync(cardToken, (decimal)amount);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId),
            "ChargeId should be a non-empty identifier");
    }

    [TestMethod]
    [DataRow("", 10.00, DisplayName = "Empty token")]
    [DataRow("   ", 10.00, DisplayName = "Whitespace token")]
    public async Task ChargeAsync_InvalidToken_ThrowsArgumentException(
        string cardToken, double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            () => _sut.ChargeAsync(cardToken, (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            () => _sut.ChargeAsync(null!, 10.00m));
    }

    [TestMethod]
    [DataRow(0.00, DisplayName = "Zero amount")]
    [DataRow(-5.00, DisplayName = "Negative amount")]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRangeException(
        double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            () => _sut.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailure()
    {
        // A declined card token should return Success = false
        var result = await _sut.ChargeAsync("tok_declined", 50.00m);

        Assert.IsFalse(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId),
            "ChargeId should still be assigned for tracking purposes");
    }

    // --- RefundAsync Tests ---

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        // Arrange – create a charge first to get a valid charge ID
        var charge = await _sut.ChargeAsync("tok_valid_visa", 25.00m);
        Assert.IsTrue(charge.Success, "Precondition: charge must succeed");

        // Act
        var refund = await _sut.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsTrue(refund.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(refund.RefundId),
            "RefundId should be a non-empty identifier");
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var result = await _sut.RefundAsync("ch_nonexistent_12345");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow("", DisplayName = "Empty chargeId")]
    [DataRow("   ", DisplayName = "Whitespace chargeId")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            () => _sut.RefundAsync(chargeId));
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            () => _sut.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_DuplicateRefund_ReturnsFailure()
    {
        // Arrange – charge and refund once
        var charge = await _sut.ChargeAsync("tok_valid_visa", 30.00m);
        Assert.IsTrue(charge.Success, "Precondition: charge must succeed");
        var firstRefund = await _sut.RefundAsync(charge.ChargeId);
        Assert.IsTrue(firstRefund.Success, "Precondition: first refund must succeed");

        // Act – attempt a second refund on the same charge
        var secondRefund = await _sut.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsFalse(secondRefund.Success,
            "Duplicate refund should not succeed");
    }

    // --- Cross-cutting concerns ---

    [TestMethod]
    public async Task ChargeAsync_MultipleCharges_ReturnDistinctChargeIds()
    {
        var charge1 = await _sut.ChargeAsync("tok_valid_visa", 10.00m);
        var charge2 = await _sut.ChargeAsync("tok_valid_visa", 20.00m);

        Assert.IsTrue(charge1.Success);
        Assert.IsTrue(charge2.Success);
        Assert.AreNotEqual(charge1.ChargeId, charge2.ChargeId,
            "Each charge should receive a unique ChargeId");
    }
}

